panel:
var battlePanel;
this.useExpball.nowState = true;
this.open = function()
{
   this.setMainHuanShou();
   this.flashView();
   this._parent.successHuanHua.closePanel();
   this.openPanel();
};
this.setHuanShou = function(target)
{
   if(this.mainRect.hitTest(_root._xmouse,_root._ymouse,true))
   {
      if(this.battleHuanShou(target) == true)
      {
         this.setMainHuanShou(target);
         return true;
      }
   }
   return false;
};
this.battleHuanShou = function(target)
{
   if(target.battle == false)
   {
      if(_parent.battleHuanShouPanel1.isOpen)
      {
         _parent.battleHuanShouPanel1.battleButton.onRelease();
      }
      _parent.huanShou.battle(target);
      battlePanel = _parent.battleHuanShouPanel1;
      return true;
   }
   if(_parent.battleHuanShouPanel1.huanShou == target)
   {
      battlePanel = _parent.battleHuanShouPanel1;
   }
   else if(_parent.battleHuanShouPanel2.huanShou == target)
   {
      battlePanel = _parent.battleHuanShouPanel2;
   }
   else
   {
      if(_parent.battleHuanShouPanel3.huanShou != target)
      {
         return false;
      }
      battlePanel = _parent.battleHuanShouPanel3;
   }
   return true;
};
this.setMainHuanShou = function(target)
{
   if(target.type)
   {
      this.mainHuanShou = target;
      this.mainHuanShouView._visible = true;
      this.mainHuanShouView.gotoAndStop(this.mainHuanShou.type);
      this.mainFen.text = "主幻兽评分:" + Math.floor(this.mainHuanShou.allFen);
      this.showInfo();
      return true;
   }
   this.mainFen.text = "";
   this.mainHuanShou = undefined;
   this.mainHuanShouView._visible = false;
   this.showInfo();
   return false;
};
this.beginHuanHua = function()
{
   if(this.mainHuanShou == undefined)
   {
      return false;
   }
   if(this.mainHuanShou.zs >= this.mainHuanShou.maxZs)
   {
      _global.sysMsg.addMsg("主幻兽的转世次数已经达到极限，不能再进行幻化了。");
      return false;
   }
   if(this.useExpball.nowState == true)
   {
      this.autoUseExpball();
   }
   if(this.mainHuanShou.levels < 30)
   {
      _global.sysMsg.addMsg("提示：转世幻化等级要求30级以上");
      return false;
   }
   if(this._parent.backPack.useThing({type:"宝石",name:"灵魂晶石"},1) == false)
   {
      _global.sysMsg.addMsg("你的背包里没有灵魂晶石。");
      return false;
   }
   this.mainHuanShou.turned();
   this.mainHuanShou.checkUp();
   this.addFen = 10;
   this.successInfo = "";
   this.successInfo += "转世次数增加1次\r";
   this.successInfo += "幻兽评分提高10分";
   this._parent.successHuanHua.openPanel(this.successInfo,this.mainHuanShou,_X,_Y);
   this._parent.flashHuanShouView();
   battlePanel.body.life = battlePanel.body.maxLife;
   return true;
};
this.flashView = function()
{
   this.setMainHuanShou(this.mainHuanShou);
};
this.infoText.html = true;
this.showInfo = function()
{
   this.infoText.htmlText = "<font color=\'#ffffff\'>转世幻化要求：\r30级以上，需要一个灵魂晶石。\r幻化后转世次数增加1次，评分加10分</font>";
   if(this.mainHuanShou != undefined)
   {
      this.infoText.htmlText += "<font color=\'#ffffff\'>\r当前转世次数" + this.mainHuanShou.zs + "\r最大转世次数" + this.mainHuanShou.maxZs + "</font>";
      if(this.mainHuanShou.zs < this.mainHuanShou.maxZs)
      {
         this.infoText.htmlText += "<font color=\'#00cc66\'>可以进行转世幻化</font>";
      }
      else
      {
         this.infoText.htmlText += "<font color=\'#ff3333\'>不能进行转世幻化</font>";
      }
   }
   else
   {
      this.infoText.htmlText += "<font color=\'#ffffff\'>，但幻兽的属性成长率不增加，同时幻兽等级也回到1级。</font>";
   }
};
this.useExpball.onRelease = function()
{
   this.nowState = !this.nowState;
};
this.autoUseExpball = function()
{
   if(this.mainHuanShou.levels < 30)
   {
      if(this.battleHuanShou(this.mainHuanShou) == false)
      {
         _global.sysMsg.addMsg("请先把主幻兽出征。");
         return false;
      }
      if(this._parent.backPack.accountThing({type:"经验球"}) >= 2)
      {
         if(this.battlePanel.setThing({type:"经验球"}) == true)
         {
            this._parent.backPack.useThing({type:"经验球"},1);
            if(this.battlePanel.setThing({type:"经验球"}) == true)
            {
               this._parent.backPack.useThing({type:"经验球"},1);
               return true;
            }
            return false;
         }
         return false;
      }
      _global.sysMsg.addMsg("你的物品栏里没有足够的经验球");
      return false;
   }
   return true;
};

